const USERS_KEY = 'impacto-bi.users';
const VERSION_KEY = 'impacto-bi.users.accessVersion';

const state = {
  map: new Map(),
  failKeys: new Set(),
  writes: []
};

globalThis.window = {
  localStorage: {
    getItem: (key) => state.map.has(key) ? state.map.get(key) : null,
    setItem: (key, value) => {
      state.writes.push(key);
      if (state.failKeys.has(key)) throw new Error('QuotaExceededError');
      state.map.set(key, String(value));
    },
    removeItem: (key) => {
      state.map.delete(key);
    }
  }
};

let failures = 0;
let checks = 0;

function check(name, condition, detail) {
  checks += 1;
  if (condition) return;
  failures += 1;
  console.log(`FALHA: ${name}`, detail === undefined ? '' : JSON.stringify(detail));
}

async function main() {
  const { departmentPages } = await Promise.resolve().then(() => jitiImport('./src/config/departmentPages').then((m) => _interopRequireWildcard(m)));
  const rules = await Promise.resolve().then(() => jitiImport('./src/lib/userAccessRules').then((m) => _interopRequireWildcard(m)));
  const storage = await Promise.resolve().then(() => jitiImport('./src/services/users/userStorage').then((m) => _interopRequireWildcard(m)));

  const osPages = departmentPages.os.map((page) => page.key);
  const accessOf = (user, id) =>
  user?.departmentPageAccess?.find((a) => a.departmentId === id)?.pageKeys ?? [];

  /**
   * Usuário Departamental sintético, criado só aqui: departamento os com
   * temporal, status e model, sem overview. A base real não é usada.
   */
  function syntheticUser() {
    return {
      id: 'tmp-001',
      name: 'Usuário Sintético',
      email: 'sintetico@impactotelecom.com',
      profile: 'Usuário Departamental',
      permissions: 'Ordens de Serviço',
      permissionKeys: ['bi.ordens-servico.access'],
      departments: ['Ordens de Serviço'],
      departmentPageAccess: [{ departmentId: 'os', pageKeys: ['temporal', 'status', 'model'] }],
      status: 'Ativo',
      lastAccess: '17/07/2026 13:47',
      initials: 'US',
      audit: {
        createdAt: '2026-01-01T00:00:00.000Z',
        createdByUserId: 'usr-000',
        createdByName: 'Seed'
      }
    };
  }

  function seedStorage(version, users) {
    state.map.clear();
    state.failKeys.clear();
    state.writes = [];
    state.map.set(USERS_KEY, JSON.stringify(users));
    if (version !== null) state.map.set(VERSION_KEY, version);
  }

  // ---------- 1. Derivação sem overview adiciona overview ----------
  const derived = rules.deriveUserAccess({
    profile: 'Usuário Departamental',
    departments: [{ departmentId: 'os', pageKeys: ['temporal', 'status'] }]
  });
  check('derivacao adiciona overview', accessOf(derived, 'os').includes('overview'));
  check(
    'derivacao nao inventa outras paginas',
    JSON.stringify(accessOf(derived, 'os')) === JSON.stringify(['overview', 'temporal', 'status'])
  );

  // ---------- 2. Ordem final segue departmentPages ----------
  const unordered = rules.deriveUserAccess({
    profile: 'Usuário Departamental',
    departments: [{ departmentId: 'os', pageKeys: ['model', 'status', 'temporal'] }]
  });
  const expectedOrder = osPages.filter((key) =>
  ['overview', 'temporal', 'status', 'model'].includes(key)
  );
  check(
    'ordem segue o catalogo',
    JSON.stringify(accessOf(unordered, 'os')) === JSON.stringify(expectedOrder)
  );
  check(
    'ordem esperada e overview, temporal, status, model',
    JSON.stringify(expectedOrder) === JSON.stringify(['overview', 'temporal', 'status', 'model'])
  );
  check(
    'padrao continua com todas menos model',
    JSON.stringify(rules.defaultDepartmentPageKeys('os')) ===
    JSON.stringify(osPages.filter((key) => key !== 'model')) &&
    rules.defaultDepartmentPageKeys('os').includes('overview')
  );

  // ---------- 3. Departamento sem overview no catálogo é inválido ----------
  const originalOsPages = departmentPages.os;
  departmentPages.os = originalOsPages.filter((page) => page.key !== 'overview');
  const withoutOverview = rules.deriveUserAccess({
    profile: 'Usuário Departamental',
    departments: [{ departmentId: 'os', pageKeys: ['status'] }]
  });
  departmentPages.os = originalOsPages;
  check('departamento sem overview no catalogo e invalido', withoutOverview === null);
  check('catalogo restaurado apos o teste', departmentPages.os === originalOsPages);

  // Administrador e Executivo seguem com Visão Geral pelas regras atuais.
  check(
    'administrador mantem overview',
    accessOf(rules.deriveUserAccess({ profile: 'Administrador' }), 'os').includes('overview')
  );
  check(
    'executivo mantem overview',
    accessOf(rules.deriveUserAccess({ profile: 'Executivo' }), 'os').includes('overview')
  );

  // ---------- 4, 5, 6 e 10. Migração de versão 1 para 2 ----------
  seedStorage('1', [syntheticUser()]);
  const migrated = storage.readStoredUsers();
  const migratedPages = accessOf(migrated?.[0], 'os');

  check(
    'cenario sintetico resulta em overview, temporal, status, model',
    JSON.stringify(migratedPages) === JSON.stringify(['overview', 'temporal', 'status', 'model']),
    migratedPages
  );
  check('modelo preservado', migratedPages.includes('model'));
  check(
    'paginas removidas continuam fora',
    osPages.
    filter((key) => !['overview', 'temporal', 'status', 'model'].includes(key)).
    every((key) => !migratedPages.includes(key))
  );
  check('somente a visao geral foi acrescentada', migratedPages.length === 4);
  check('marca avancou para 2', state.map.get(VERSION_KEY) === '2');
  check('gravou uma unica vez', state.writes.filter((key) => key === USERS_KEY).length === 1);
  check(
    'demais campos preservados',
    migrated?.[0].name === 'Usuário Sintético' &&
    migrated?.[0].status === 'Ativo' &&
    migrated?.[0].lastAccess === '17/07/2026 13:47' &&
    migrated?.[0].audit?.createdAt === '2026-01-01T00:00:00.000Z' &&
    migrated?.[0].departments.join() === 'Ordens de Serviço'
  );
  check(
    'nao reaplicou o realinhamento da versao 1',
    migratedPages.length < rules.defaultDepartmentPageKeys('os').length
  );

  // ---------- 7. Base versão 0 executa as duas migrações ----------
  seedStorage(null, [{ ...syntheticUser(), profile: 'Gestor' }]);
  const fromZero = storage.readStoredUsers();
  const fromZeroPages = accessOf(fromZero?.[0], 'os');
  check('versao 0 migra o perfil legado', fromZero?.[0].profile === 'Usuário Departamental');
  // Realinhamento completo: todas as páginas padrão mais o model preservado.
  check(
    'versao 0 aplica o realinhamento completo',
    JSON.stringify(fromZeroPages) === JSON.stringify(osPages),
    fromZeroPages
  );
  check('versao 0 mantem o model liberado', fromZeroPages.includes('model'));
  check('versao 0 inclui overview', fromZeroPages.includes('overview'));
  check('versao 0 grava uma unica vez', state.writes.filter((key) => key === USERS_KEY).length === 1);
  check('versao 0 termina na marca 2', state.map.get(VERSION_KEY) === '2');

  // ---------- 8. Base versão 2 não migra novamente ----------
  seedStorage('2', [syntheticUser()]);
  const untouched = storage.readStoredUsers();
  check(
    'versao 2 nao altera a colecao',
    JSON.stringify(accessOf(untouched?.[0], 'os')) ===
    JSON.stringify(['temporal', 'status', 'model'])
  );
  check('versao 2 nao regrava', state.writes.filter((key) => key === USERS_KEY).length === 0);

  // ---------- 9. Falha de storage mantém coleção e versão anteriores ----------
  seedStorage('1', [syntheticUser()]);
  const originalJson = state.map.get(USERS_KEY);
  state.failKeys.add(VERSION_KEY);
  const failedMigration = storage.readStoredUsers();
  check(
    'falha de storage devolve a migracao em memoria',
    accessOf(failedMigration?.[0], 'os').includes('overview')
  );
  check('falha de storage preserva a colecao persistida', state.map.get(USERS_KEY) === originalJson);
  check('falha de storage preserva a versao anterior', state.map.get(VERSION_KEY) === '1');
  state.failKeys.clear();
  const retried = storage.readStoredUsers();
  check(
    'migracao e tentada de novo com o mesmo resultado',
    JSON.stringify(retried) === JSON.stringify(failedMigration)
  );
  check('apos o retry a marca avanca', state.map.get(VERSION_KEY) === '2');

  console.log(`\n${checks - failures}/${checks} verificacoes passaram`);
  if (failures) process.exitCode = 1;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
}); /* v9-530c4870ac6f6deb */
